void increment_kind_allocation(RuntimeHeapStats &stats, HeapObjectKind kind) {
  switch (kind) {
  case HeapObjectKind::Instance:
    ++stats.instance_allocations;
    return;
  case HeapObjectKind::List:
  case HeapObjectKind::Tuple:
  case HeapObjectKind::Set:
    ++stats.array_allocations;
    return;
  case HeapObjectKind::Map:
    ++stats.map_allocations;
    return;
  case HeapObjectKind::Closure:
    ++stats.closure_allocations;
    return;
  }
}

bool decode_keyword_utf8_codepoint(const std::string &source,
                                   std::size_t offset, std::uint32_t *codepoint,
                                   std::size_t *byte_count) {
  if (offset >= source.size()) {
    return false;
  }
  const unsigned char byte0 = static_cast<unsigned char>(source[offset]);
  if (byte0 < 0x80U) {
    *codepoint = byte0;
    *byte_count = 1;
    return true;
  }

  std::uint32_t value = 0;
  std::size_t count = 0;
  if ((byte0 & 0xE0U) == 0xC0U) {
    value = byte0 & 0x1FU;
    count = 2;
  } else if ((byte0 & 0xF0U) == 0xE0U) {
    value = byte0 & 0x0FU;
    count = 3;
  } else if ((byte0 & 0xF8U) == 0xF0U) {
    value = byte0 & 0x07U;
    count = 4;
  } else {
    return false;
  }

  if (offset + count > source.size()) {
    return false;
  }
  for (std::size_t i = 1; i < count; ++i) {
    const unsigned char byte = static_cast<unsigned char>(source[offset + i]);
    if ((byte & 0xC0U) != 0x80U) {
      return false;
    }
    value = (value << 6U) | (byte & 0x3FU);
  }
  *codepoint = value;
  *byte_count = count;
  return true;
}

bool host_secure_random_bytes(std::size_t count, std::string *out,
                              std::string *error) {
  if (out == nullptr) {
    if (error != nullptr) {
      *error = "secure random output is null";
    }
    return false;
  }
  out->assign(count, '\0');
  if (count == 0U) {
    return true;
  }
#if defined(__APPLE__) || defined(__FreeBSD__) || defined(__OpenBSD__) ||      \
    defined(__NetBSD__)
  arc4random_buf(&(*out)[0], out->size());
  return true;
#elif defined(__linux__)
  char *cursor = &(*out)[0];
  std::size_t remaining = out->size();
  while (remaining > 0U) {
    const ssize_t got = getrandom(cursor, remaining, 0);
    if (got < 0) {
      if (errno == EINTR) {
        continue;
      }
      if (error != nullptr) {
        *error = std::string("getrandom failed: ") + std::strerror(errno);
      }
      return false;
    }
    if (got == 0) {
      if (error != nullptr) {
        *error = "getrandom returned no entropy";
      }
      return false;
    }
    cursor += got;
    remaining -= static_cast<std::size_t>(got);
  }
  return true;
#else
  if (error != nullptr) {
    *error = "secure random is not supported on this platform";
  }
  return false;
#endif
}

bool keyword_identifier_start(std::uint32_t codepoint) {
  const bool ascii_alpha = (codepoint >= 'A' && codepoint <= 'Z') ||
                           (codepoint >= 'a' && codepoint <= 'z');
  const bool cyrillic = (codepoint >= 0x0400U && codepoint <= 0x052FU) ||
                        (codepoint >= 0x1C80U && codepoint <= 0x1C8FU) ||
                        (codepoint >= 0x2DE0U && codepoint <= 0x2DFFU) ||
                        (codepoint >= 0xA640U && codepoint <= 0xA69FU);
  const bool greek = (codepoint >= 0x0370U && codepoint <= 0x03FFU) ||
                     (codepoint >= 0x1F00U && codepoint <= 0x1FFFU);
  return ascii_alpha || cyrillic || greek || codepoint == '_';
}

bool keyword_identifier_part(std::uint32_t codepoint) {
  return keyword_identifier_start(codepoint) ||
         (codepoint >= '0' && codepoint <= '9');
}

bool reserved_keyword_identifier(const std::string &text) {
  static const std::unordered_set<std::string_view> keywords = {
      "and",        "attr",    "break",   "case",  "class", "class_method",
      "class_prop", "def",     "do",      "elif",  "else",  "elsif",
      "export",     "extend",  "false",   "from",  "if",    "import",
      "in",         "include", "loop",    "mixin", "noop",  "not",
      "null",       "or",      "package", "pass",  "prop",  "true",
      "unless",     "until",   "when",    "while"};
  return keywords.find(text) != keywords.end();
}

bool keyword_identifier_text(const std::string &text) {
  if (text.empty() || reserved_keyword_identifier(text)) {
    return false;
  }

  std::size_t offset = 0;
  std::uint32_t codepoint = 0;
  std::size_t byte_count = 0;
  if (!decode_keyword_utf8_codepoint(text, offset, &codepoint, &byte_count) ||
      !keyword_identifier_start(codepoint)) {
    return false;
  }
  offset += byte_count;

  while (offset < text.size()) {
    const unsigned char byte = static_cast<unsigned char>(text[offset]);
    if ((byte == '?' || byte == '!') && offset + 1U == text.size()) {
      return true;
    }
    if (!decode_keyword_utf8_codepoint(text, offset, &codepoint, &byte_count) ||
        !keyword_identifier_part(codepoint)) {
      return false;
    }
    offset += byte_count;
  }
  return true;
}

